import {
  Clipboard as ClipboardPrimitive,
  useClipboard,
  useClipboardContext,
} from '@ark-ui/solid/clipboard';
import { clsx } from 'clsx';
import type { ComponentProps } from 'solid-js';
import { children, splitProps } from 'solid-js';
import { CheckIcon, CopyIcon } from '@/lib/moduix/icons/ui/Icons';
import styles from './Clipboard.module.css';

function Clipboard(props: ComponentProps<typeof ClipboardPrimitive.Root>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <ClipboardPrimitive.Root
      class={clsx(styles.root, local.class)}
      {...others}
      data-slot="clipboard-root"
    />
  );
}

function ClipboardRootProvider(props: ComponentProps<typeof ClipboardPrimitive.RootProvider>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <ClipboardPrimitive.RootProvider
      class={clsx(styles.root, local.class)}
      {...others}
      data-slot="clipboard-root-provider"
    />
  );
}

function ClipboardLabel(props: ComponentProps<typeof ClipboardPrimitive.Label>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <ClipboardPrimitive.Label
      class={clsx(styles.label, local.class)}
      {...others}
      data-slot="clipboard-label"
    />
  );
}

function ClipboardControl(props: ComponentProps<typeof ClipboardPrimitive.Control>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <ClipboardPrimitive.Control
      class={clsx(styles.control, local.class)}
      {...others}
      data-slot="clipboard-control"
    />
  );
}

function ClipboardInput(props: ComponentProps<typeof ClipboardPrimitive.Input>) {
  const [local, others] = splitProps(props, ['asChild', 'class']);

  return (
    <ClipboardPrimitive.Input
      asChild={local.asChild}
      class={clsx(!local.asChild && styles.input, local.class)}
      {...others}
      data-slot="clipboard-input"
    />
  );
}

function ClipboardTrigger(props: ComponentProps<typeof ClipboardPrimitive.Trigger>) {
  const [local, others] = splitProps(props, ['asChild', 'class']);

  return (
    <ClipboardPrimitive.Trigger
      asChild={local.asChild}
      class={clsx(!local.asChild && styles.trigger, local.class)}
      {...others}
      data-slot="clipboard-trigger"
    />
  );
}

function ClipboardIndicator(props: ComponentProps<typeof ClipboardPrimitive.Indicator>) {
  const [local, others] = splitProps(props, ['children', 'class', 'copied']);
  const resolvedChildren = children(() => local.children);

  return (
    <ClipboardPrimitive.Indicator
      class={clsx(styles.indicator, local.class)}
      copied={local.copied ?? <CheckIcon />}
      {...others}
      data-slot="clipboard-indicator"
    >
      {resolvedChildren() ?? <CopyIcon />}
    </ClipboardPrimitive.Indicator>
  );
}

function ClipboardValueText(props: ComponentProps<typeof ClipboardPrimitive.ValueText>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <ClipboardPrimitive.ValueText
      class={clsx(styles.valueText, local.class)}
      {...others}
      data-slot="clipboard-value-text"
    />
  );
}

const ClipboardContext = ClipboardPrimitive.Context;

export {
  Clipboard,
  ClipboardContext,
  ClipboardControl,
  ClipboardIndicator,
  ClipboardInput,
  ClipboardLabel,
  ClipboardRootProvider,
  ClipboardTrigger,
  ClipboardValueText,
  useClipboard,
  useClipboardContext,
};

@layer moduix.components {
  .root {
    display: flex;
    flex-direction: column;
    gap: var(--moduix-clipboard-gap, var(--moduix-spacing-1-5));
    width: 100%;
    color: var(--moduix-color-foreground);
  }

  .label {
    font-size: var(--moduix-text-sm);
    font-weight: var(--moduix-weight-medium);
    line-height: var(--moduix-line-height-text-sm);
  }

  .control {
    display: flex;
    align-items: center;
    gap: var(--moduix-clipboard-control-gap, var(--moduix-spacing-2));
    width: 100%;
  }

  .input,
  .trigger {
    box-sizing: border-box;
    min-height: var(--moduix-clipboard-height, var(--moduix-size-md));
    margin: 0;
    border: var(--moduix-border-width-sm) solid
      var(--moduix-clipboard-border-color, var(--moduix-color-border));
    border-radius: var(--moduix-clipboard-radius, var(--moduix-radius-md));
    color: var(--moduix-color-foreground);
    font: inherit;
    transition:
      background-color var(--moduix-transition-default),
      border-color var(--moduix-transition-default),
      outline-color var(--moduix-transition-default),
      opacity var(--moduix-transition-default);

    &:disabled {
      pointer-events: none;
      opacity: var(--moduix-opacity-disabled);
    }
  }

  .input {
    width: 100%;
    min-width: 0;
    padding: var(--moduix-spacing-1) var(--moduix-spacing-3);
    background-color: var(--moduix-clipboard-input-bg, var(--moduix-color-background));
    font-size: var(--moduix-text-md);
    line-height: var(--moduix-line-height-text-md);
    outline: var(--moduix-focus-ring-inset-width) solid transparent;
    outline-offset: calc(var(--moduix-border-width-sm) * -1);

    &::placeholder {
      color: var(--moduix-color-muted-foreground);
    }

    &:focus-visible {
      outline-color: var(--moduix-color-ring);
    }
  }

  .trigger {
    display: inline-flex;
    flex-shrink: 0;
    align-items: center;
    justify-content: center;
    gap: var(--moduix-spacing-2);
    padding-inline: var(--moduix-spacing-4);
    background-color: var(--moduix-clipboard-trigger-bg, var(--moduix-color-background));
    appearance: none;
    font-size: var(--moduix-text-sm);
    font-weight: var(--moduix-weight-medium);
    line-height: var(--moduix-line-height-text-sm);
    user-select: none;
    white-space: nowrap;
    cursor: pointer;

    & :where(svg) {
      width: var(--moduix-clipboard-icon-size, var(--moduix-spacing-4));
      height: var(--moduix-clipboard-icon-size, var(--moduix-spacing-4));
      flex-shrink: 0;
    }

    @media (hover: hover) {
      &:hover:not(:disabled) {
        background-color: var(--moduix-clipboard-trigger-bg-hover, var(--moduix-color-accent));
      }
    }

    &:focus-visible {
      outline: var(--moduix-focus-ring-width) solid var(--moduix-color-ring);
      outline-offset: calc(var(--moduix-border-width-sm) * -1);
    }

    &:active:not(:disabled) {
      opacity: 0.94;
    }
  }

  .indicator {
    display: inline-flex;
    flex-shrink: 0;
    align-items: center;
    justify-content: center;
  }

  .valueText {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
}
